// Cloudflare Worker entry. OpenNext generates `.open-next/worker.js` (the Next handler) at build time; this wraps it to
// answer sign-out before Next and to add `scheduled()` (cron). wrangler `main` points here. Excluded from `tsc` (the
// generated import exists only after `opennextjs-cloudflare build`).
// @ts-expect-error - generated by `opennextjs-cloudflare build`
import openNextHandler from './.open-next/worker.js';

import { SIGN_OUT_PATH, authSignOutRequest, isSameOriginRequest, signOutResponse } from '@repo/auth/sign-out';

type Ctx = { waitUntil: (p: Promise<unknown>) => void };
type FetchHandler = (request: Request, env: unknown, ctx: Ctx) => Promise<Response>;
const nextFetch = (openNextHandler as { fetch: FetchHandler }).fetch;

interface Env {
    CRON_SECRET?: string;
    // Service binding to this same Worker (wrangler.jsonc): lets the cron handler call our own API routes.
    WORKER_SELF_REFERENCE?: { fetch: (req: Request) => Promise<Response> };
}

/**
 * `POST /api/sign-out`: every session cookie expired and a 204 at once, then better-auth's own sign-out runs through the
 * Next handler in `waitUntil` with the ORIGINAL cookies, so the session row is still deleted. Sign-out takes one short
 * request instead of a full page round trip.
 */
function answerSignOut(request: Request, env: Env, ctx: Ctx): Response {
    if (!isSameOriginRequest(request)) return new Response(null, { status: 403 });
    ctx.waitUntil(
        nextFetch(authSignOutRequest(request), env, ctx)
            .then((res) => res.body?.cancel())
            .catch((err: unknown) => console.error('[sign-out] background sign-out failed:', err)),
    );
    return signOutResponse(request);
}

/**
 * Each cron expression (wrangler.jsonc `triggers.crons`, UTC; production only - staging has none) maps to the internal
 * routes it runs. One expression can drive several jobs: they run one after another in one wake-up instead of a second
 * schedule waking the Worker (and the database) again a minute later. Jobs are registered in @repo/cron.
 */
const CRON_JOBS: Record<string, string[]> = {
    '0 * * * *': ['/api/cron/hourly'],
    '30 0 * * *': ['/api/cron/daily'],
};

export default {
    ...openNextHandler,

    async fetch(request: Request, env: Env, ctx: Ctx) {
        if (request.method === 'POST' && new URL(request.url).pathname === SIGN_OUT_PATH) {
            return answerSignOut(request, env, ctx);
        }
        return nextFetch(request, env, ctx);
    },

    async scheduled(event: { cron: string }, env: Env, ctx: Ctx) {
        const paths = CRON_JOBS[event.cron];
        if (!paths?.length) {
            console.warn(`[cron] no job mapped for "${event.cron}"`);
            return;
        }
        const run = async (path: string) => {
            const req = new Request(`https://self${path}`, {
                method: 'POST',
                headers: { Authorization: `Bearer ${env.CRON_SECRET ?? ''}` },
            });
            try {
                const res = env.WORKER_SELF_REFERENCE ? await env.WORKER_SELF_REFERENCE.fetch(req) : await nextFetch(req, env, ctx);
                console.log(`[cron] ${event.cron} -> ${path} -> ${res.status}`);
            } catch (err) {
                console.error(`[cron] ${path} failed:`, err);
            }
        };
        // One after another: they share one database compute window; `run` never rejects, so one failure can't stop the rest.
        ctx.waitUntil((async () => { for (const p of paths) await run(p); })());
    },
};
